import { ref } from 'vue'

const PermissionSystem = {
  setup() {
    const userRoles = ref(['admin', 'editor', 'viewer'])
    const currentRole = ref('viewer')

    const hasPermission = (permission) => {
      const permissions = {
        admin: ['create', 'edit', 'delete', 'view'],
        editor: ['edit', 'view'],
        viewer: ['view']
      }
      return permissions[currentRole.value].includes(permission)
    }

    const selectRole = (role) => {
      currentRole.value = role
    }

    const currentPermissions = () => {
      const permissions = {
        admin: ['create', 'edit', 'delete', 'view'],
        editor: ['edit', 'view'],
        viewer: ['view']
      }
      return permissions[currentRole.value]
    }

    return {
      userRoles,
      currentRole,
      hasPermission,
      selectRole,
      currentPermissions
    }
  },
  template: `
    <div>
      <h2>Permission System</h2>
      <div>
        <h3>Select Role</h3>
        <button 
          v-for="role in userRoles" 
          :key="role"
          @click="selectRole(role)"
          :class="{ active: currentRole === role }"
        >
          {{ role }}
        </button>
      </div>
      <div>
        <h3>Current Role: {{ currentRole }}</h3>
        <p>Permissions: {{ currentPermissions().join(', ') }}</p>
      </div>
      <!-- Add permission check demonstration here -->
    </div>
  `
}
